from math import sqrt

def max_polygon_area(segments):
    def distance(p1, p2):
        return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def area_of_triangle(p1, p2, p3):
        return abs(p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1])) / 2.0

    def convex_hull(points):
        if len(points) <= 3:
            return points
        lower = []
        upper = []
        for point in sorted(points):
            while len(lower) >= 2 and area_of_triangle(lower[-2], lower[-1], point) < 0:
                lower.pop()
            lower.append(point)
            while len(upper) >= 2 and area_of_triangle(upper[-2], upper[-1], point) > 0:
                upper.pop()
            upper.append(point)
        return lower[:-1] + upper[:-1]

    def polygon_area(points):
        return sum(area_of_triangle(points[i], points[(i+1)%len(points)], points[(i+2)%len(points)]) for i in range(len(points)))

    n = len(segments)
    if n < 3:
        return 0.0

    # Generate all possible points on the circle
    points = [(segments[i]/2, 0) for i in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            d = distance(points[i], points[j])
            if d == segments[i]:
                points[j] = (points[j][0], points[j][1] + sqrt(d**2 - (segments[i]/2)**2))
            elif d == segments[j]:
                points[i] = (points[i][0] + sqrt(d**2 - (segments[j]/2)**2), points[i][1])

    hull = convex_hull(points)
    return polygon_area(hull)

