from math import sqrt

def shoelace_formula(coords):
    n = len(coords)
    area = 0.5 * abs(sum(x * y - y * x for x, y in zip(coords, coords[1:] + coords[:1])))
    return area

def is_valid_polygon(segments):
    total_length = sum(segments)
    for r in range(3, len(segments) + 1):
        for combo in combinations(segments, r):
            if sum(combo) == total_length:
                return True
    return False

def max_area_of_pen(n, segments):
    if not is_valid_polygon(segments):
        return 0.0

    max_area = 0.0
    for r in range(3, len(segments) + 1):
        for combo in combinations(segments, r):
            if sum(combo) == sum(segments):
                coords = [(i, 0) for i in combo]
                area = shoelace_formula(coords)
                if area > max_area:
                    max_area = area

    return max_area

